from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class DirectionDataAzimuth(SchemaObject):
    low = SchemaField(name='low')
    high = SchemaField(name='high')
    step = SchemaField(name='step')

    def __init__(self, low, high, step):
        self.low = low
        self.high = high
        self.step = step

        super(DirectionDataAzimuth, self).__init__()


class DirectionDataTiltInformation(SchemaObject):
    low = SchemaField(name='low')
    high = SchemaField(name='high')
    step = SchemaField(name='step')

    def __init__(self, low, high, step):
        self.low = low
        self.high = high
        self.step = step

        super(DirectionDataTiltInformation, self).__init__()


class DirectionData(SchemaObject):
    azimuth = SchemaField(name='azimuth', klass=DirectionDataAzimuth)
    tilt_information = SchemaField(name='tiltInformation', klass=DirectionDataTiltInformation)

    def __init__(self, azimuth, tilt_information):
        self.azimuth = azimuth
        self.tilt_information = tilt_information

        super(DirectionData, self).__init__()


class DetailedStatus(SchemaObject):
    id = SchemaField(name='id', not_null=True)
    status = SchemaField(name='status', not_null=True)
    error_text = SchemaField(name='errorText')

    def __init__(self, id, status, error_text):
        self.id = id
        self.status = status
        self.error_text = error_text

        super(DetailedStatus, self).__init__()


class ErrorCode(SchemaObject):
    code = SchemaField(name='code', optional=True)
    description = SchemaField(name='description', optional=True)

    def __init__(self, code, description):
        self.code = code
        self.description = description

        super(ErrorCode, self).__init__()


class Operation(SchemaObject):
    id = SchemaField(name='id', not_null=True)
    status = SchemaField(name='status', not_null=True)
    detailed_statuses = SchemaField(name='detailedStatuses', optional=True, many=True, klass=DetailedStatus)
    error_message = SchemaField(name='errorMessage', optional=True)
    error_code = SchemaField(name='errorCode', optional=True, klass=ErrorCode)

    def __init__(self, id, status, detailed_statuses, error_message, error_code):
        self.id = id
        self.status = status
        self.detailed_statuses = detailed_statuses
        self.error_message = error_message
        self.error_code = error_code

        super(Operation, self).__init__()


class GetDirectionDataResponse(Operation):
    direction_data = SchemaField(name='directionData', optional=True, klass=DirectionData)

    def __init__(self, id, status, detailed_statuses, error_message, error_code, direction_data):
        self.id = id
        self.status = status
        self.detailed_statuses = detailed_statuses
        self.error_message = error_message
        self.error_code = error_code
        self.direction_data = direction_data

        super(GetDirectionDataResponse, self).__init__(id, status, detailed_statuses, error_message, error_code)
